initial_condition:
with {
   the SUT containing an initial state
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Delete Entity by Id with Response Status Code set to 404     and
        Delete Entity by Id with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/ResourceNotFound'     and
        Delete Entity by Id with Response body containing 'title' element
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/entities/{id}'
        method set to 'DELETE'
        Delete Entity Request with id set to '${entity_id}'
}
